import test from 'node:test';import assert from 'node:assert/strict';
import * as S from '../src/spectral.mjs';
const near=(a,b,t=1e-8)=>assert.ok(Math.abs(a-b)<t,`${a} != ${b}`);
const vacuum={rayleighTau550:0,aerosolTau550:0,greyTau:0};
test('CP5 spectral API exists (not the CP4 blackbody-only path)',()=>assert.equal(typeof S.spectralStarFlux,'function'));
test('V is an actual named passband, separate from photopic Y',()=>{const a=S.spectralStarFlux({vmag:0,bv:-.2},90,vacuum),b=S.spectralStarFlux({vmag:0,bv:1.5},90,vacuum);near(a.vFlux,1);near(b.vFlux,1);assert.ok(Math.abs(a.xyz[1]-b.xyz[1])>.005);});
test('magnitude anchors received V flux without distance dimming',()=>{for(const bv of [-.2,0,.65,1.5]){const a=S.spectralStarFlux({vmag:0,bv,distancePc:2},90,vacuum),b=S.spectralStarFlux({vmag:5,bv,distancePc:200},90,vacuum);near(a.vFlux/b.vFlux,100);for(let k=0;k<3;k++)near(a.rgb[k]/b.rgb[k],100);}});
test('verified standard belongs to its own HIP identity',()=>{const a=S.selectSpectrum({hip:91262,bv:-.001}),b=S.selectSpectrum({hip:49669,bv:-.087});assert.equal(a.kind,'observed-spectrophotometric-shape');assert.equal(b.kind,'observed-spectrophotometric-shape');assert.notDeepEqual(a.samples,b.samples);});
test('quality-rejected Denebola standard stays rejected, not silently repaired',()=>assert.notEqual(S.selectSpectrum({hip:57632,bv:.09}).kind,'observed-spectrophotometric-shape'));
test('template is a declared estimate, never a measurement of another star',()=>{const t=S.selectSpectrum({hip:999999,spectralType:'A0V',bv:0});assert.equal(t.kind,'observed-standard-template');assert.equal(t.measuredForThisSource,false);assert.ok(t.source);});
test('peculiar/composite/wrong class cannot borrow template by colour alone',()=>{for(const spectralType of ['A0V+M2V','A0Vp','M2Iab','B7III',null])assert.equal(S.selectSpectrum({hip:99,spectralType,bv:.1}).kind,'B-V-constrained-continuum');});
test('unknown B-V and spectrum remain unknown, with neutral-display proxy',()=>{const x=S.selectSpectrum({bv:null});assert.equal(x.kind,'unknown-neutral-display');assert.equal(x.temperatureProxyK,null);assert.equal(x.colourFallback,true);});
test('blackbody family is numerically constrained to measured B-V',()=>{for(const bv of [-.2,0,.65,1.5,2])near(S.syntheticBV(S.selectSpectrum({bv}).samples),bv,2e-6);});
test('out-of-range colour does not become a fabricated temperature',()=>assert.equal(S.selectSpectrum({bv:3}).kind,'unknown-neutral-display'));
test('provided spectra require provenance and contain positive energy',()=>{assert.throws(()=>S.selectSpectrum({sed:{samples:Array(95).fill(1)}}));assert.throws(()=>S.selectSpectrum({sed:{samples:Array(95).fill(0),source:'fixture'}}));assert.throws(()=>S.selectSpectrum({sed:{samples:Array(95).fill(-1),source:'fixture'}}));});
test('provided measured spectrum overrides defaults and is V-normalised',()=>{const x=S.selectSpectrum({sed:{samples:Array(95).fill(2),source:'test fixture, not astronomical measurement',kind:'provided-spectrum'}});near(S.passbandIntegral(x.samples,'V'),1);});
test('tabulated CIE values replace analytic fitting error',()=>{assert.deepEqual(S.cieTableAt(555),[.5120501,1,.005749999]);assert.deepEqual(S.cieTableAt(450),[.3362,.038,1.77211]);});
test('wavelength extinction dims and reddens without colour renormalisation',()=>{const s={bv:0,vmag:0};const a=S.spectralStarFlux(s,90,vacuum),b=S.spectralStarFlux(s,5,{rayleighTau550:.1,aerosolTau550:.1});assert.ok(b.vFlux<a.vFlux*.4);assert.ok(b.rgb[0]/b.rgb[2]>a.rgb[0]/a.rgb[2]);});
test('cloud factor is linear once and below-horizon light is zero',()=>{const s={bv:0,vmag:0},a=S.spectralStarFlux(s,45,vacuum),b=S.spectralStarFlux(s,45,{...vacuum,cloudTransmission:.4});near(b.vFlux/a.vFlux,.4);assert.deepEqual(S.spectralStarFlux(s,-1,vacuum).rgb,[0,0,0]);});
test('monochrome V detector preserves V ordering and has no fictional colour',()=>{const a=S.spectralStarFlux({bv:1.5,vmag:2},90,vacuum,{response:'V-monochrome'});near(a.rgb[0],a.rgb[1]);near(a.rgb[1],a.rgb[2]);near(a.rgb[0],10**(-.8));});
test('gamut mapping preserves XYZ-Y rather than arbitrary peak normalisation',()=>{const a=S.spectralStarFlux({bv:-.3,vmag:0},90,vacuum);near(.2126*a.rgb[0]+.7152*a.rgb[1]+.0722*a.rgb[2],a.xyz[1],1e-8);});
test('borrowed template is colour-constrained rather than replacing measured B-V',()=>{for(const bv of [-.04,0,.06]){const s=S.selectSpectrum({hip:666666,spectralType:'A0V',bv});assert.equal(s.kind,'observed-standard-template');near(S.syntheticBV(s.samples),bv,2e-6);}});
